#include "Diagnostics.h"
#include "MotionState.h"
#include "ContextAnalysis.h"
#include <iostream>
#include <stdexcept>
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
nova::Sound tone(double cents=0){nova::Sound s;s.sampleRate=22050;s.left.resize(22050);s.right=s.left;double hz=440*std::pow(2.,cents/1200);for(size_t i=0;i<s.left.size();++i)s.left[i]=s.right[i]=.2f*std::sin(2*nova::pi*hz*i/s.sampleRate);nova::analyse(s);return s;}
int main(){try{
 nova::MotionState a,b;for(int i=0;i<30;++i)a.advance(1./30,.8f,true,true);for(int i=0;i<60;++i)b.advance(1./60,.8f,true,true);check(std::abs(a.level-b.level)<1e-5&&std::abs(a.activity-b.activity)<1e-5,"frame-rate-independent easing");check(a.level>.79f&&a.level<=.8f,"bounded attack");float before=a.level;a.advance(.03,0,false,true);check(a.level>0&&a.level<before,"smooth release");a.advance(.03,.2f,false,false);check(a.level==.2f&&a.activity==0&&a.phase==0,"reduced motion snaps");a.advance(NAN,NAN,true,true);check(std::isfinite(a.level)&&std::isfinite(a.phase),"non-finite input safe");
 auto source=tone(37);auto t=nova::centredTarget(nova::makeTarget(source,69,source.sampleRate,false));nova::Sound centred;centred.sampleRate=t.rate;centred.left=t.left;centred.right=t.right;nova::analyse(centred);check(centred.tonal&&std::abs(1200*std::log2(centred.estimatedHz/440))<1.2,"A-centred corrects global detuning");check(std::abs(1200*std::log2(source.estimatedHz/440)-37)<1.2,"A original unchanged");
 auto correct=tone();auto d=nova::diagnose(source,correct,69);check(d.expectedNote==69&&std::abs(d.targetErrorCents)<1.2,"diagnostic uses centred MIDI target");auto wrong=nova::diagnose(source,correct,57);check(std::abs(wrong.targetErrorCents-1200)<1.2&&wrong.warnings.find("octava")!=std::string::npos,"explicit octave mismatch detected");
 nova::Params p;p.engine=0;p.waveA=p.waveB=0;p.mix=0;p.fineTune=0;p.sub=p.fm=p.noise=p.detune=p.lfoDepth=p.reverb=p.delay=p.chorus=0;p.unison=false;p.cutoff=19000;p.sustain=1;p.attack=.001f;p.envAmount=0;std::array<int,nova::arpSteps> pattern{};auto low=nova::renderRecreation(correct,p,nullptr,nullptr,false,pattern,120,.8f,57);nova::analyse(low);check(low.tonal&&std::abs(1200*std::log2(low.estimatedHz/220))<1.2,"manual reference root used in A/B");
 nova::Sound unstable;unstable.sampleRate=16000;unstable.left.resize(80000);unstable.right=unstable.left;double phase=0;for(size_t i=0;i<unstable.left.size();++i){double time=i/unstable.sampleRate,hz=440*std::pow(2.,46*std::sin(2*nova::pi*.5*time)/1200);phase+=2*nova::pi*hz/unstable.sampleRate;unstable.left[i]=unstable.right[i]=.2f*std::sin(phase);}std::atomic<bool> cancel{false};auto context=nova::analyseContext(unstable,cancel);check(context.rejectedUnstable>0,"unstable context regions rejected");
 auto target=nova::makeTarget(correct,69,22050,false);auto report=nova::fitInstrument(target,p,140,cancel);check(report.fit.valid,"candidate search valid");int count=0;double minimum=1e9;for(const auto& c:report.candidates)if(c.valid){++count;minimum=std::min(minimum,c.error);check(std::isfinite(c.parameters.master)&&c.parameters.master>=-36&&c.parameters.master<=0,"candidate gain bounded");if(c.pitchMeasured)check(std::abs(c.pitchErrorCents)<=65,"alternatives exclude confirmed wrong notes");}check(count>=3&&minimum<=report.fit.bestError+1e-8,"at least three real evaluated engine alternatives");
 std::cout<<"PASS: UI easing/rates/reduced motion, original versus centred A, intended-note diagnostics, manual A/B root, context stability rejection and evaluated alternatives\n";
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
